/**
 * Content migrated from ypnus.com's WordPress install (see docs/AWS_MIGRATION.md,
 * item 1: "Export the 138 pages / 335 posts from WordPress to MDX ... and generate a
 * 301 redirect map from every old URL, so rankings survive.").
 *
 * pages.json / posts.json / redirects.json are generated by a one-off export script
 * (not checked in) that pulls from https://ypnus.com/wp-json/wp/v2/{pages,posts} and:
 *   - dedupes the 335 WordPress posts down to ~171 canonical ones (328 of the 335
 *     were accidental duplicate-title republishes; the later-modified copy of each
 *     pair was kept as canonical, the other's old URL redirects to it)
 *   - buckets the 138 pages by their WordPress path prefix (markets/, loan-types/,
 *     vs/, platform/, features/, mlo-marketing/, territory/, or top-level)
 *   - drops WordPress's own /about, /features and /blog page content where this app
 *     already has a hand-built native page at that path (native wins; WP's old URL
 *     just redirects there) — see AGENTS.md's "additive, ypnus.com stays live" rule
 *   - remaps /onboarding (a WP marketing page, "Set Up Your YPN USA Mortgage
 *     Website") to /website-setup, since /onboarding is this app's own logged-in
 *     account-setup flow, not marketing copy
 *
 * This is additive: nothing here touches ypnus.com, which remains the live,
 * authoritative site until DNS actually cuts over (not yet — see AWS_MIGRATION.md).
 */
import type { BlogPost } from "@/content/blog";
import pagesData from "./pages.json";
import postsData from "./posts.json";
import redirectsData from "./redirects.json";

export interface WpImportedPage {
  slug: string;
  title: string;
  description: string;
  html: string;
  date: string;
  modified: string;
  wpId: number;
}

interface RawPost {
  slug: string;
  title: string;
  description: string;
  date: string;
  author: string;
  readingMinutes: number;
  html: string;
  wpId: number;
}

type PageSections = Record<string, WpImportedPage[]>;
const SECTIONS = pagesData as PageSections;

export const WP_TOP_PAGES: readonly WpImportedPage[] = SECTIONS.top ?? [];
export const WP_MARKET_PAGES: readonly WpImportedPage[] = SECTIONS.markets ?? [];
export const WP_LOAN_TYPE_PAGES: readonly WpImportedPage[] = SECTIONS["loan-types"] ?? [];
export const WP_VS_PAGES: readonly WpImportedPage[] = SECTIONS.vs ?? [];
export const WP_PLATFORM_PAGES: readonly WpImportedPage[] = SECTIONS.platform ?? [];
export const WP_FEATURES_SUBPAGES: readonly WpImportedPage[] = SECTIONS.features ?? [];
export const WP_MLO_MARKETING_PAGES: readonly WpImportedPage[] = SECTIONS["mlo-marketing"] ?? [];
export const WP_TERRITORY_PAGES: readonly WpImportedPage[] = SECTIONS.territory ?? [];
export const WP_RESOURCE_PAGES: readonly WpImportedPage[] = SECTIONS.resources ?? [];

export function getWpPage(list: readonly WpImportedPage[], slug: string): WpImportedPage | undefined {
  return list.find((p) => p.slug === slug);
}

export const WP_POSTS: readonly BlogPost[] = (postsData as RawPost[]).map((p) => ({
  slug: p.slug,
  title: p.title,
  description: p.description,
  date: p.date,
  author: p.author,
  readingMinutes: p.readingMinutes,
  html: p.html,
}));

/** Old WordPress path (with and without trailing slash) -> new app path. */
export const WP_REDIRECTS: Readonly<Record<string, string>> = redirectsData as Record<string, string>;
